IF coalesce((t->>'missing')::boolean,false) THEN DELETE FROM public.utilisateurs WHERE id=-91899;END IF;
IF t->>'setup'<>'' THEN BEGIN EXECUTE t->>'setup';EXCEPTION WHEN raise_exception THEN IF t->>'name'='mismatched campaign owner refused' AND SQLERRM='CROSS_CLIENT_ASSIGNMENT_DENIED' THEN RAISE EXCEPTION 'rollback fixture' USING ERRCODE='Z0001';ELSE RAISE;END IF;END;END IF;
